// Escape de literal SQL. Apóstrofo em gancho ("Ninguém 'te' conta") quebra
// qualquer INSERT montado por interpolação — por isso todo texto passa aqui.
const q = (v) => (v === null || v === undefined || v === '' ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'");
const n = (v) => (v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : String(Number(v)));

const post = $('Um Post Por Vez').first().json;
const raw = $input.first().json;
const dados = raw.data || [];

// A Graph API alterna entre values[0].value e total_value.value conforme a
// métrica e a versão — aceitar os dois evita zerar silenciosamente.
const pegar = (nome) => {
  const m = dados.find(x => x.name === nome);
  const v = m?.values?.[0]?.value ?? m?.total_value?.value;
  return v === undefined || v === null ? null : Number(v);
};

const hoje = new Date().toISOString().slice(0, 10);

// ON CONFLICT (post_id, data_ref): a coleta é diária e precisa ser idempotente,
// senão duas execuções no mesmo dia inflam toda soma de alcance.
const sql = `INSERT INTO metricas (id, post_id, data_coleta, data_ref, alcance, salvamentos, compartilhamentos, comentarios)
VALUES (gen_random_uuid()::text, ${q(post.id)}, NOW(), ${q(hoje)}, ${n(pegar('reach'))}, ${n(pegar('saved'))}, ${n(pegar('shares'))}, ${n(pegar('comments'))})
ON CONFLICT (post_id, data_ref) DO UPDATE SET
  alcance = EXCLUDED.alcance,
  salvamentos = EXCLUDED.salvamentos,
  compartilhamentos = EXCLUDED.compartilhamentos,
  comentarios = EXCLUDED.comentarios,
  data_coleta = NOW();`;

return [{ json: { sql, postId: post.id } }];

const rows = $input.all().map(i => i.json);

// Menos de 3 posts: o prompt do relatório manda declarar incerteza, e com 1-2
// posts a IA inventaria padrão. Melhor não gastar a chamada.
if (rows.length < 3) {
  return [{ json: { suficiente: false, totalPosts: rows.length } }];
}

const PROMPT = "Você é analista de performance de conteúdo no Instagram.
Recebe as métricas da semana e produz um relatório acionável.

REGRAS:
1. Baseie CADA conclusão em dados explícitos. Se os dados não sustentam
   uma conclusão, declare a incerteza — nunca invente padrão sem evidência.
2. Métricas em ordem de importância para o algoritmo: salvamentos >
   compartilhamentos > retenção 3s > alcance > comentários > curtidas.
3. Compare posts ENTRE SI na mesma semana (relativo, não absoluto).
4. Hipóteses devem ser testáveis na próxima semana (uma variável por vez).
5. A recomendação final deve ser específica o suficiente para virar
   instrução direta de produção (ex: "priorizar padrão X, evitar horário Y").

SAÍDA: APENAS JSON válido:
{"padroesVencedores":[{"padrao":"...","evidencia":"..."}],
"padroesPerdedores":[{"padrao":"...","evidencia":"..."}],
"hipoteses":["..."],
"recomendacaoProximaSemana":"..."}

EXEMPLO:
ENTRADA (métricas da semana):
[
 {"post":"P1","padrao":"lista numerada","formato":"carrossel","alcance":12400,"salvamentos":890,"compartilhamentos":210,"retention3s":null,"follows":65},
 {"post":"P2","padrao":"pergunta provocativa","formato":"reel","alcance":8200,"salvamentos":140,"compartilhamentos":95,"retention3s":0.38,"follows":12},
 {"post":"P3","padrao":"contraste","formato":"reel","alcance":21000,"salvamentos":310,"compartilhamentos":640,"retention3s":0.61,"follows":180}
]

SAÍDA:
{"padroesVencedores":[
{"padrao":"contraste em Reel","evidencia":"P3 teve 640 compartilhamentos (3x P1) e retention3s de 61%, muito acima dos 38% de P2"},
{"padrao":"carrossel para salvamento","evidencia":"P1 gerou 890 salvamentos, o maior da semana, apesar de alcance intermediário — formato de referência tem alta taxa de guarda"}
],
"padroesPerdedores":[
{"padrao":"pergunta provocativa em Reel","evidencia":"P2 teve a pior retenção (38%) e apenas 140 salvamentos com 8.200 de alcance — o gancho em forma de pergunta não sustentou os 3s iniciais"}
],
"hipoteses":[
"Reels com estrutura de contraste retêm melhor porque o conflito aparece nos primeiros 3s — testar 2 Reels de contraste na próxima semana",
"Carrosséis convertem mais em salvamentos do que em alcance — testar carrossel com gancho de contraste para combinar os dois comportamentos"
],
"recomendacaoProximaSemana":"Produzir 2 Reels com padrão contraste e 1 carrossel com gancho de contraste. Evitar ganchos em formato de pergunta até novo teste. Publicar no mesmo horário de P3 para isolar a variável de padrão."}

AGORA ANALISE AS MÉTRICAS:
{{metricas}}";
const prompt = PROMPT.replace('{{metricas}}', JSON.stringify(rows, null, 1));

return [{ json: { suficiente: true, prompt, totalPosts: rows.length } }];

// Escape de literal SQL. Apóstrofo em gancho ("Ninguém 'te' conta") quebra
// qualquer INSERT montado por interpolação — por isso todo texto passa aqui.
const q = (v) => (v === null || v === undefined || v === '' ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'");
const n = (v) => (v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : String(Number(v)));

const raw = $input.first().json;
const texto = (raw.content || []).filter(b => b.type === 'text').map(b => b.text).join('')
  .replace(/```(?:json)?/gi, '').trim();

let rel;
try { rel = JSON.parse(texto); }
catch (e) { throw new Error('Relatório em JSON inválido: ' + texto.slice(0, 300)); }

if (!rel.recomendacaoProximaSemana) throw new Error('Relatório sem recomendação: ' + texto.slice(0, 300));

// A recomendação entra na fila de pauta com prioridade 10 e as hipóteses com 5:
// é isso que fecha o loop — o relatório define o que o Workflow A produz.
const pautas = [
  { tema: rel.recomendacaoProximaSemana, prioridade: 10 },
  ...(rel.hipoteses || []).slice(0, 3).map(h => ({ tema: h, prioridade: 5 })),
];

const valores = pautas
  .map(p => `(${q(String(p.tema).slice(0, 500))}, (SELECT id FROM nichos WHERE status = 'ativo' ORDER BY score DESC NULLS LAST LIMIT 1), 'pendente', ${p.prioridade}, NOW())`)
  .join(',\n');

const sql = `INSERT INTO topicos (tema, nicho_id, status, prioridade, criado_em) VALUES ${valores} RETURNING id;`;
return [{ json: { sql, pautas: pautas.length, relatorio: rel } }];
